// vendored from SuperInstance/quilt-studio @ 52dfb8e (packages/quilt-floor/src/multigrid.mjs) — byte-identical
// The multigrid — de Bruijn's pentagrid and its dual, the rhombic Penrose
// floor (P3). The iceberg: the 1D Fibonacci floor and the Strip were a
// cross-section; here is the crystal.
//
// Construction (all positions derived, none trusted from memory):
//   • N=5 families of lines; family k has normal n_k at angle kπ/N
//     (pentagrid: 0°, 36°, 72°, 108°, 144°). Line (k,j):
//     n_k·x = (j + γ_k)·spacing. γ is the shift vector; γ=0 is singular
//     (triple concurrences, tested), generic γ gives proper Penrose.
//   • Arrangement vertices = pairwise intersections; each has a ℤ^N lift
//     (cell indices j_i = round(n_i·x − γ_i)) and defining lines.
//   • Faces = index vectors adjacent to each arrangement segment. A face
//     with index vector j sits at
//         x(j) = (2/N) · Σ_k (j_k + γ_k + ½) · n_k          (N=5 → 2/5)
//     because Σ n_k n_kᵀ = (N/2)·I — the strip center is the least-squares
//     center of the five strips. Verified to 1e-12 in tests.
//   • Dual edges: each arrangement segment separates exactly two faces
//     j⁺ and j⁻; they differ by ±1 in exactly the segment's family k, and
//     x(j⁺) − x(j⁻) = (2/N)·n_k EXACTLY — every dual edge has the same
//     length and one of the five normal directions. That is the Penrose
//     P3 tiling (de Bruijn's theorem; here re-derived, not quoted).
//   • Dual tiles: the faces around each arrangement vertex form a rhombus
//     (degree 4 at generic γ): thick (72°) or thin (36°) by the angle
//     between the two defining normals.
//
// THE ICEBERG TEST (multigrid.test.mjs): dual edges of family k lie on
// lines with two-gap intercept structure in ratio φ, sequenced as the
// Fibonacci word — the 1D floor hiding inside every direction of the 2D
// crystal. Anti-vacuity: detuned normals break the two-gap law exactly.

import { PHI } from './golden.mjs';

export const TAU = Math.PI * 2;

// Cell indices are FLOORS, not rounds: the face with index j is the strip
// j ≤ n·x − γ < j+1. Round() silently picks the neighbor half the time —
// that one bug bent every downstream constant (edge lengths came out
// 2φ/5 and 2·SQ/5 instead of the unique 2/5).
function tieFloor(r) {
  const q = Math.round(r);
  return Math.abs(r - q) < 1e-9 ? q : Math.floor(r);
}

// THE GOLDEN GAPS (pinned by probe, locked by tests): family-k edge-lines
// of the pentagrid dual have intercept gaps drawn from
//   S   = (2/5)·sin(2π/5)·φ⁻³
//   L   = (2/5)·sin(2π/5)·φ⁻² = S·φ
//   S+L = (2/5)·sin(2π/5)·φ⁻¹
// In the patch core, consecutive gaps take exactly {L, S+L} (ratio φ,
// no two L adjacent); S appears as their difference and as a rare clipped
// residual. The detuned grid (alternating ±2° normals) breaks all of this
// — 12 distinct gap values, smallest ratio 1.43 — anti-vacuity in the
// test file. Edge length (2/5) is the lattice unit; sin(2π/5) is the
// altitude of the thick rhombus.
export function goldenGaps() {
  const a = (2 / 5) * Math.sin(2 * Math.PI / 5);
  return { S: a * Math.pow(PHI, -3), L: a * Math.pow(PHI, -2), SL: a * Math.pow(PHI, -1) };
}

// Normal of family k for an N-grid: angle k·π/N.
export function gridNormal(k, N = 5) {
  const a = Math.PI * k / N;
  return [Math.cos(a), Math.sin(a)];
}

// Dual-tiling edge direction for family k: exactly n_k (each dual edge
// telescopes to (2/N)·n_k — see file header).
export function edgeDirection(k, N = 5) {
  return gridNormal(k, N);
}

export class Multigrid {
  constructor({ N = 5, gamma = null, reach = 3, spacing = 1 } = {}) {
    this.N = N;
    this.gamma = gamma ?? new Array(N).fill(0.5);
    this.reach = reach;
    this.spacing = spacing;
    this.normals = Array.from({ length: N }, (_, k) => gridNormal(k, N));
  }

  lineCount() { return 2 * this.reach + 1; }

  // ---- arrangement: vertices and segments -----------------------------

  // Pairwise intersections between distinct families, deduped by position
  // (the lift is DATA, not identity — distinct vertices can share a lift
  // vector when they sit in the same index slab; that bug bit once).
  arrangementVertices() {
    const { N, normals, gamma, spacing, reach } = this;
    const found = new Map();
    const vs = [];
    for (let k = 0; k < N; k++) {
      for (let l = k + 1; l < N; l++) {
        const [ax, ay] = normals[k], [bx, by] = normals[l];
        const det = ax * by - ay * bx;
        for (let j = -reach; j <= reach; j++) {
          for (let m = -reach; m <= reach; m++) {
            const ck = (j + gamma[k]) * spacing;
            const cl = (m + gamma[l]) * spacing;
            const x = (ck * by - cl * ay) / det;
            const y = (ax * cl - bx * ck) / det;
            const key = `${Math.round(x * 1e9)},${Math.round(y * 1e9)}`;
            if (found.has(key)) {
              // triple concurrence: record the extra defining line
              const v = vs[found.get(key)];
              v.lines.push({ k, j });
              continue;
            }
            found.set(key, vs.length);
            const lift = new Array(N);
            for (let i = 0; i < N; i++)
              lift[i] = tieFloor((normals[i][0] * x + normals[i][1] * y) / spacing - gamma[i]);
            vs.push({ x, y, lift, lines: [{ k, j }, { k: l, j: m }] });
          }
        }
      }
    }
    return vs;
  }

  // Segments of the arrangement, as TRUE 1-faces: each line is split at its
  // crossings with EVERY other family — including lines one step beyond the
  // reach window (they still split what we can see). Splitting only at the
  // computed vertices merged across out-of-reach lines and produced midpoint
  // ties that made the two side-faces disagree (the 6 bent edges the probe
  // caught). Each segment carries its two adjacent faces' index vectors.
  arrangementSegments() {
    const { N, normals, gamma, spacing, reach } = this;
    const segs = [];
    const d = normals.map(n => [-n[1], n[0]]);
    for (let k = 0; k < N; k++) {
      for (let j = -reach; j <= reach; j++) {
        // anchor point on line (k,j): a = (j+γ_k)·n_k (per unit spacing)
        const a = [(j + gamma[k]) * spacing * normals[k][0], (j + gamma[k]) * spacing * normals[k][1]];
        const ts = [];
        for (let q = 0; q < N; q++) {
          if (q === k) continue;
          const den = normals[q][0] * d[k][0] + normals[q][1] * d[k][1];
          if (Math.abs(den) < 1e-12) continue;
          for (let m = -reach - 1; m <= reach + 1; m++) {
            const num = (m + gamma[q]) * spacing - (normals[q][0] * a[0] + normals[q][1] * a[1]);
            ts.push(num / den);
          }
        }
        ts.sort((x, y) => x - y);
        const face = (t, sign) => {
          const mx = a[0] + t * d[k][0] + sign * 1e-7 * spacing * normals[k][0];
          const my = a[1] + t * d[k][1] + sign * 1e-7 * spacing * normals[k][1];
          const f = new Array(N);
          for (let q = 0; q < N; q++) {
            if (q === k) { f[q] = sign > 0 ? j : j - 1; continue; }
            f[q] = tieFloor((normals[q][0] * mx + normals[q][1] * my) / spacing - gamma[q]);
          }
          return f;
        };
        for (let i = 0; i + 1 < ts.length; i++) {
          const t1 = ts[i], t2 = ts[i + 1];
          if (t2 - t1 < 1e-9) continue;               // concurrence: zero-length
          const tm = (t1 + t2) / 2;
          segs.push({ k, j, t1, t2, above: face(tm, 1), below: face(tm, -1) });
        }
      }
    }
    return segs;
  }

  // ---- the dual: faces (tiling vertices), edges, tiles ---------------

  // Face = index vector; position = strip-center formula. Existence is
  // constructional: a face appears iff some arrangement segment borders it.
  faces() {
    const { N, normals, gamma } = this;
    const segs = this.arrangementSegments();
    const map = new Map();
    for (const s of segs) {
      for (const f of [s.above, s.below]) {
        const key = f.join(',');
        if (map.has(key)) continue;
        let x = 0, y = 0;
        for (let k = 0; k < N; k++) {
          const w = (f[k] + gamma[k] + 0.5);
          x += w * normals[k][0];
          y += w * normals[k][1];
        }
        x *= 2 / N; y *= 2 / N;
        map.set(key, { lift: f, x, y });
      }
    }
    return [...map.values()];
  }

  // Dual edges: one per arrangement segment; endpoints are its two faces.
  dualEdges() {
    const segs = this.arrangementSegments();
    const faces = this.faces();
    const idOf = new Map(faces.map((f, i) => [f.lift.join(','), i]));
    const edges = [];
    for (const s of segs) {
      const a = idOf.get(s.above.join(','));
      const b = idOf.get(s.below.join(','));
      if (a === undefined || b === undefined) continue;
      edges.push({ a, b, family: s.k, line: s.j });
    }
    return { faces, edges };
  }

  // Dual tiles: the faces around each arrangement vertex form a rhombus.
  // Corner lifts: vertex.lift with the two defining families shifted by
  // the four quadrant combinations.
  dualTiles() {
    const { N } = this;
    const vs = this._av ?? (this._av = this.arrangementVertices());
    const { faces, edges } = this.dualEdges();
    const idOf = new Map(faces.map((f, i) => [f.lift.join(','), i]));
    const adj = new Map();
    for (const e of edges) {
      if (!adj.has(e.a)) adj.set(e.a, []);
      if (!adj.has(e.b)) adj.set(e.b, []);
      adj.get(e.a).push(e.b);
      adj.get(e.b).push(e.a);
    }
    const tiles = [];
    for (const v of vs) {
      if (v.lines.length > 2) continue;          // concurrence: no rhombus
      const [d1, d2] = v.lines;
      const corners = [];
      let ok = true;
      for (const s1 of [0, -1]) {
        for (const s2 of [0, -1]) {
          // the four cells around the vertex: base lift, defining components
          // shifted to the line's lower side (cell j has the line as its
          // LOWER boundary — the floor convention, same as the strip)
          const f = v.lift.slice();
          f[d1.k] += s1;
          f[d2.k] += s2;
          const id = idOf.get(f.join(','));
          if (id === undefined) { ok = false; break; }
          corners.push(id);
        }
        if (!ok) break;
      }
      if (!ok) continue;
      const [n1, n2] = [this.normals[d1.k], this.normals[d2.k]];
      let ang = Math.abs(Math.atan2(n1[0] * n2[1] - n1[1] * n2[0], n1[0] * n2[0] + n1[1] * n2[1]));
      if (ang > Math.PI / 2) ang = Math.PI - ang;
      tiles.push({ corners, angle: ang, families: [d1.k, d2.k], at: [v.x, v.y] });
    }
    return { faces, edges, tiles };
  }

  // THE ICEBERG PROBE: dual edges of family k lie on lines x·n_k⊥ = c.
  // For the true Penrose: consecutive distinct c's have exactly two gap
  // values in ratio φ, sequenced as a Fibonacci word (pinned in tests).
  interceptGaps(k) {
    const n = this.normals[k];
    const perp = [-n[1], n[0]];
    const { faces, edges } = this.dualEdges();
    const set = new Map();
    for (const e of edges) {
      if (e.family !== k) continue;
      const f = faces[e.a];
      const c = perp[0] * f.x + perp[1] * f.y;
      set.set(Math.round(c * 1e9), c);           // dedup lines, keep raw
    }
    const vals = [...set.values()].sort((a, b) => a - b);
    const gaps = [];
    for (let i = 0; i + 1 < vals.length; i++) gaps.push(vals[i + 1] - vals[i]);
    return { intercepts: vals, gaps };
  }

  // Window probe: perp-space projection of face lifts. The physical plane
  // in index space is spanned by c=(cos πk/N)_k, s=(sin πk/N)_k; a face's
  // index vector y = j + γ + ½ projects there, and the remainder is the
  // window coordinate. Boundedness + central symmetry pinned in tests.
  windowCoords() {
    const { N, gamma } = this;
    const c = Array.from({ length: N }, (_, k) => Math.cos(Math.PI * k / N));
    const s = Array.from({ length: N }, (_, k) => Math.sin(Math.PI * k / N));
    const cN = Math.hypot(...c), sN = Math.hypot(...s);
    const faces = this.faces();
    return faces.map(f => {
      const y = f.lift.map((j, k) => j + gamma[k] + 0.5);
      const pc = y.reduce((a, yk, k) => a + yk * c[k], 0) / (cN * cN);
      const ps = y.reduce((a, yk, k) => a + yk * s[k], 0) / (sN * sN);
      return y.map((yk, k) => yk - pc * c[k] - ps * s[k]);
    });
  }

  // Kernel tenancy: faces become cells, dual edges become typed links,
  // one patch per bind — a tenant like every floor instrument.
  host(kernel, { name = 'mg' } = {}) {
    const { faces, edges } = this.dualEdges();
    faces.forEach((f, i) => kernel.bind(`${name}.v.${i}`, { x: f.x, y: f.y, lift: f.lift }, { index: i }));
    for (const e of edges) kernel.link(`${name}.v.${e.a}`, `${name}.v.${e.b}`, `fam${e.family}`);
    kernel.bind(`${name}.params`, { N: this.N, gamma: this.gamma, reach: this.reach });
    return { vertices: faces.length, edges: edges.length };
  }
}

// vendored from SuperInstance/quilt-studio @ 52dfb8e (packages/quilt-floor/src/spline.mjs) — byte-identical
// spline.mjs — IARS: Identity-Anchored Rational Splines, the floor's analogue seam.
//
// The fleet's spaces are exact discrete worlds (integer (k,s) grid identities,
// ℤ⁵ lifts, hash-chained ids) stitched by ad-hoc teleports. IARS is the
// missing continuous layer between them, under fleet doctrine:
//
//   INTEGERS OWN IDENTITY; RATIONALS OWN MOTION; FLOATS ONLY MEASURE.
//
//   controls = native identities (lifted to ℚ, exact integers preferred)
//   knots    = ℚ (BigInt) — knot multiplicity is the smoothness dial:
//              mult k at a knot ⇒ C^{p−k} there (the analogue dial)
//   weights  = ℚ — Pythagorean Δ keeps cos(Δ/2) rational (3-4-5 ⇒ 4/5),
//              so a rational quadratic IS an exact circle arc
//   evaluate = BigInt-rational de Boor (Piegl & Tiller A2.1–A2.3) — no f64
//              in the pipeline; a discrete hop is the rounding of a motion
//   snap     = nearest identity by ℚ distance — derived, never hand-carried
//
// Honest limit: non-Pythagorean weights (cos 30° = √3/2) have no rational
// shadow — measure against the f64 shadow and say so, same stance as π in
// golden.mjs. Arc length is a MEASURE: adaptive Simpson on the exact speed
// function, returned as a float, never as identity.
//
// Ref: Piegl & Tiller, The NURBS Book, 2e, A2.1–A2.3 / A5.1; quilt-gan's
// fabric-nurbs probe (11/11); /tmp/nurbs/SYNTHESIS.md (IARS spec). The
// dersBasisFuns row-swap lives INSIDE the k-loop (A2.3) — the
// [null,null,2]-corruption class is what this discipline pins.

import {
  makeRat, floatToRat, ratAdd, ratSub, ratMul, ratDiv, ratNeg,
  ratEq, ratIsZero, ratCmp, ratAbs, ratToNumber, ratToString,
} from './commensurate.mjs';

const ZERO = makeRat(0n);
const ONE = makeRat(1n);

// toRat — rat | number | BigInt → canonical rat. Numbers take the exact
// dyadic path (floatToRat), so 0.1 is honestly 3602879701896397/2^55.
export function toRat(x) {
  if (typeof x === 'bigint') return makeRat(x);
  if (typeof x === 'number') {
    const r = floatToRat(x);
    if (!r) throw new Error('toRat: non-finite');
    return r;
  }
  if (x && typeof x === 'object' && typeof x.num === 'bigint' && typeof x.den === 'bigint') return x;
  throw new Error('toRat: unsupported operand');
}

// points may be {x,y} objects or coordinate arrays (ℚ¹⁶-ready).
const pointCoords = p => Array.isArray(p) ? p.map(toRat) : [toRat(p.x), toRat(p.y)];

const qPoint = coords => coords.map(c => (c && typeof c === 'object' && typeof c.num === 'bigint') ? c : toRat(c));

// ---------------------------------------------------------------- construction
// makeSpline({degree, knots, controls, weights?})
//   knots    : non-decreasing, length = controls.length + degree + 1
//   controls : identity points ({x,y} | [rat...]); stored as ℚ coordinate arrays
//   weights  : default 1 (B-spline); rationals make it NURBS
export function makeSpline({ degree: p, knots, controls, weights } = {}) {
  if (!Number.isInteger(p) || p < 1) throw new Error('makeSpline: degree must be a positive integer');
  const U = knots.map(toRat);
  const P = controls.map(pointCoords);
  const w = (weights ?? controls.map(() => 1)).map(toRat);
  const n = P.length - 1;
  if (n < 0) throw new Error('makeSpline: no control points');
  if (U.length !== n + p + 2) throw new Error(`makeSpline: knot vector length ${U.length} ≠ ${n + p + 2} controls+degree+1`);
  for (let i = 1; i < U.length; i++) if (ratCmp(U[i], U[i - 1]) < 0) throw new Error('makeSpline: knots must be non-decreasing');
  if (w.length !== P.length) throw new Error('makeSpline: weights.length ≠ controls.length');
  for (const wi of w) if (ratIsZero(wi)) throw new Error('makeSpline: zero weight (projective point) rejected');
  const dim = P[0].length;
  for (const pt of P) if (pt.length !== dim) throw new Error('makeSpline: ragged control points');
  return { degree: p, knots: U, controls: P, weights: w, dim };
}

// ---------------------------------------------------------------- Piegl A2.1 — exact span
export function findSpanRat(p, U, u) {
  const n = U.length - p - 2;
  if (ratCmp(u, U[n + 1]) >= 0) return n;
  if (ratCmp(u, U[p]) <= 0) return p;
  let lo = p, hi = n + 1, mid = (lo + hi) >> 1;
  while (ratCmp(u, U[mid]) < 0 || ratCmp(u, U[mid + 1]) >= 0) {
    if (ratCmp(u, U[mid]) < 0) hi = mid; else lo = mid;
    mid = (lo + hi) >> 1;
  }
  return mid;
}

// ---------------------------------------------------------------- Piegl A2.2 — basis in ℚ
// Guard: coincident knots give zero denominators off the active cone; the
// corresponding terms vanish (0/0 → 0), matching the float reference.
const qdiv = (a, b) => ratIsZero(b) ? ZERO : ratDiv(a, b);

export function basisFunsRat(span, u, p, U) {
  const N = new Array(p + 1).fill(null).map(() => ZERO);
  const left = new Array(p + 1), right = new Array(p + 1);
  N[0] = ONE;
  for (let j = 1; j <= p; j++) {
    left[j] = ratSub(u, U[span + 1 - j]);
    right[j] = ratSub(U[span + j], u);
    let saved = ZERO;
    for (let r = 0; r < j; r++) {
      const den = ratAdd(left[j - r], right[r + 1]);
      const t = qdiv(N[r], den);
      N[r] = ratAdd(saved, ratMul(right[r + 1], t));
      saved = ratMul(left[j - r], t);
    }
    N[j] = saved;
  }
  return N;
}

// ---------------------------------------------------------------- Piegl A2.3 — basis derivatives in ℚ
// THE ROW-SWAP LIVES INSIDE THE k-LOOP. (The [null,null,2]-corruption class:
// hoisting [s1,s2] = [s2,s1] outside once poisoned C'' with a transposed row,
// silently nulling curvature vetoes. Both-kernels discipline starts at home.)
export function dersBasisFunsRat(span, u, p, U, nDers) {
  const d = Array.from({ length: nDers + 1 }, () => new Array(p + 1).fill(null).map(() => ZERO));
  const ndu = Array.from({ length: p + 1 }, () => new Array(p + 1).fill(null).map(() => ZERO));
  const left = new Array(p + 1), right = new Array(p + 1);
  ndu[0][0] = ONE;
  for (let j = 1; j <= p; j++) {
    left[j] = ratSub(u, U[span + 1 - j]);
    right[j] = ratSub(U[span + j], u);
    let saved = ZERO;
    for (let r = 0; r < j; r++) {
      ndu[j][r] = ratAdd(right[r + 1], left[j - r]);
      const temp = qdiv(ndu[r][j - 1], ndu[j][r]);
      ndu[r][j] = ratAdd(saved, ratMul(right[r + 1], temp));
      saved = ratMul(left[j - r], temp);
    }
    ndu[j][j] = saved;
  }
  for (let j = 0; j <= p; j++) d[0][j] = ndu[j][p];
  const a = [[], []];
  for (let r = 0; r <= p; r++) {
    let s1 = 0, s2 = 1;
    a[0][0] = ONE;
    for (let k = 1; k <= nDers; k++) {
      let d_ = ZERO;
      const rk = r - k, pk = p - k;
      if (r >= k) { a[s2][0] = qdiv(a[s1][0], ndu[pk + 1][rk]); d_ = ratMul(a[s2][0], ndu[rk][pk]); }
      const j1 = rk >= -1 ? 1 : -rk, j2 = (r - 1 <= pk) ? k - 1 : p - r;
      for (let j = j1; j <= j2; j++) {
        a[s2][j] = qdiv(ratSub(a[s1][j], a[s1][j - 1]), ndu[pk + 1][rk + j]);
        d_ = ratAdd(d_, ratMul(a[s2][j], ndu[rk + j][pk]));
      }
      if (r <= pk) {
        a[s2][k] = ratNeg(qdiv(a[s1][k - 1], ndu[pk + 1][r]));
        d_ = ratAdd(d_, ratMul(a[s2][k], ndu[r][pk]));
      }
      d[k][r] = d_;
      [s1, s2] = [s2, s1]; // INSIDE the k-loop — Piegl A2.3, non-negotiable
    }
  }
  let r = BigInt(p);
  for (let k = 1; k <= nDers; k++) {
    for (let j = 0; j <= p; j++) d[k][j] = makeRat(d[k][j].num * r, d[k][j].den);
    r *= BigInt(p - k);
  }
  return d;
}

// ---------------------------------------------------------------- evaluation (exact)
// evalSpline(spline, t) → ℚ coordinate array. BigInt de Boor, no f64 anywhere.
export function evalSpline(spline, t) {
  const { degree: p, knots: U, controls: P, weights: w } = spline;
  const u = toRat(t);
  const n = P.length - 1;
  if (ratCmp(u, U[0]) <= 0) return P[0].map(c => ({ ...c }));
  if (ratCmp(u, U[U.length - 1]) >= 0) return P[n].map(c => ({ ...c }));
  const span = findSpanRat(p, U, u);
  const N = basisFunsRat(span, u, p, U);
  const dim = P[0].length;
  const A = new Array(dim).fill(null).map(() => ZERO);
  let W = ZERO;
  for (let i = 0; i <= p; i++) {
    const idx = span - p + i;
    const c = ratMul(N[i], w[idx]);
    W = ratAdd(W, c);
    for (let dd = 0; dd < dim; dd++) A[dd] = ratAdd(A[dd], ratMul(c, P[idx][dd]));
  }
  if (ratIsZero(W)) throw new Error('evalSpline: zero homogeneous weight');
  return A.map(x => ratDiv(x, W));
}

// evalDeriv(spline, t, k) → k-th derivative of the RATIONAL curve, exact ℚ.
// Homogeneous derivs A^{(j)} = Σ N_i^{(j)} w_i P_i, then Leibniz quotient.
export function evalDeriv(spline, t, k = 1) {
  if (k < 1 || k > 2) throw new Error('evalDeriv: k must be 1 or 2');
  const { degree: p, knots: U, controls: P, weights: w } = spline;
  const u = toRat(t);
  const n = P.length - 1;
  const span = findSpanRat(p, U, u);
  const dN = dersBasisFunsRat(span, u, p, U, k);
  const dim = P[0].length;
  const A = Array.from({ length: k + 1 }, () => new Array(dim).fill(null).map(() => ZERO));
  const Wd = new Array(k + 1).fill(null).map(() => ZERO);
  for (let j = 0; j <= k; j++) {
    for (let i = 0; i <= p; i++) {
      const idx = span - p + i;
      const c = ratMul(dN[j][i], w[idx]);
      Wd[j] = ratAdd(Wd[j], c);
      for (let dd = 0; dd < dim; dd++) A[j][dd] = ratAdd(A[j][dd], ratMul(c, P[idx][dd]));
    }
  }
  const W0 = Wd[0];
  if (ratIsZero(W0)) throw new Error('evalDeriv: zero homogeneous weight');
  const W0sq = ratMul(W0, W0);
  const out = new Array(dim).fill(null).map(() => ZERO);
  for (let dd = 0; dd < dim; dd++) {
    if (k === 1) {
      out[dd] = ratDiv(ratSub(ratMul(A[1][dd], W0), ratMul(A[0][dd], Wd[1])), W0sq);
    } else {
      const W1sq = ratMul(Wd[1], Wd[1]);
      const t1 = ratDiv(
        ratSub(ratSub(ratMul(A[2][dd], W0), ratMul(A[0][dd], Wd[2])), ratMul(makeRat(2n), ratMul(A[1][dd], Wd[1]))),
        W0sq);
      const t2 = ratDiv(ratMul(makeRat(2n), ratMul(A[0][dd], W1sq)), ratMul(W0sq, W0));
      out[dd] = ratAdd(t1, t2);
    }
  }
  return out;
}

// ---------------------------------------------------------------- measurement (floats, honestly)
// curvatureMeasure — κ = |det(C′,C″)| / |C′|³. Float measure of exact ℚ values.
export function curvatureMeasure(spline, t) {
  const d1 = evalDeriv(spline, t, 1).map(ratToNumber);
  const d2 = evalDeriv(spline, t, 2).map(ratToNumber);
  if (d1.length !== 2) throw new Error('curvatureMeasure: 2D only');
  const num = Math.abs(d1[0] * d2[1] - d1[1] * d2[0]);
  const den = Math.pow(Math.hypot(d1[0], d1[1]), 3);
  return den === 0 ? 0 : num / den;
}

// arcLengthMeasure — adaptive Simpson on |C′|. A float, because length is
// a measurement, never an identity.
export function arcLengthMeasure(spline, t0 = 0, t1 = 1, tol = 1e-12) {
  const a = toRat(t0), b = toRat(t1);
  if (ratCmp(b, a) <= 0) return 0;
  // measurement layer: float parameter space, exact eval inside — floats
  // only measure; the speed function itself is ℚ end-to-end.
  const lo = ratToNumber(a), hi = ratToNumber(b);
  const sf = x => { const d = evalDeriv(spline, floatToRat(x), 1).map(ratToNumber); return Math.hypot(...d); };
  const S = (l, r) => { const m = (l + r) / 2; return (r - l) / 6 * (sf(l) + 4 * sf(m) + sf(r)); };
  const adapt = (l, r, whole, eps, depth) => {
    const m = (l + r) / 2;
    const sl = S(l, m), sr = S(m, r);
